import { defineService, implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { items } from '@wix/data';
import { fetchFieldOptions as fetchFieldOptionsUtil, loadCollectionSchema, createReferencedCollectionItem as createReferencedCollectionItemUtil, transformFields, } from './cms-utils.js';
/**
 * Utility function to extract error messages consistently
 */
function extractErrorMessage(err, fallback) {
    return err instanceof Error ? err.message : fallback;
}
/**
 * Service definition for the CMS Collection service.
 */
export const CmsCollectionServiceDefinition = defineService('cms-collection');
/**
 * Converts platform Filter object into a WixDataFilter by chaining Wix Data SDK filter methods.
 * All filter conditions are chained on a single filter object (implicit AND logic).
 *
 * @param filter - Filter object with field paths and values/operators
 * @returns WixDataFilter object with all conditions chained
 *
 * @example
 * // Simple equality filters (AND between fields)
 * {
 *   "status": "published",
 *   "category": "tech"
 * }
 * // Result: status="published" AND category="tech"
 *
 * @example
 * // Range filters with comparison operators
 * {
 *   "price": { "$gte": 10, "$lte": 100 },
 *   "stock": { "$gt": 0 }
 * }
 * // Result: price>=10 AND price<=100 AND stock>0
 *
 * @example
 * // Array operators (OR within a field)
 * {
 *   "tags": { "$hasSome": ["javascript", "react"] },
 *   "categories": { "$hasAll": ["frontend", "tutorial"] }
 * }
 * // Result: (tags contains "javascript" OR "react") AND (categories contains both "frontend" AND "tutorial")
 *
 * @example
 * // String operators
 * {
 *   "title": { "$contains": "headless" },
 *   "slug": { "$startsWith": "blog-" },
 *   "email": { "$endsWith": "@example.com" }
 * }
 * // Result: title contains "headless" AND slug starts with "blog-" AND email ends with "@example.com"
 *
 * @example
 * // Existence operators
 * {
 *   "description": { "$isNotEmpty": true },
 *   "deletedAt": { "$isEmpty": true }
 * }
 * // Result: description has a value AND deletedAt is empty
 *
 * @example
 * // Mixed operators (real-world example: blue or red shirts in stock, priced $20-50)
 * {
 *   "category": "shirts",
 *   "color": { "$hasSome": ["blue", "red"] },
 *   "price": { "$gte": 20, "$lte": 50 },
 *   "inStock": { "$gt": 0 }
 * }
 * // Result: category="shirts" AND (color="blue" OR color="red") AND price>=20 AND price<=50 AND inStock>0

 * @example
 * ```ts
 * const colorFilter = buildWixDataFilter({ color: { $hasSome: ['yellow', 'red'] } });
 * const modelFilter = buildWixDataFilter({ model: { $eq: 'Toyota' } });
 * const combinedFilter = colorFilter.and(modelFilter);
 * const query = items.query('Cars').filter(combinedFilter);
 * ```
 */
function buildWixDataFilter(filter) {
    // Ensure filter is not null before processing
    if (!filter) {
        return items.filter();
    }
    // Start with a single filter object and chain all conditions
    let wixFilter = items.filter();
    for (const [fieldId, value] of Object.entries(filter)) {
        if (value === null || value === undefined) {
            continue;
        }
        if (typeof value === 'object' && !Array.isArray(value)) {
            // Handle operators - chain all operators for the field
            for (const [operator, operandValue] of Object.entries(value)) {
                if (operandValue === null || operandValue === undefined) {
                    continue;
                }
                switch (operator) {
                    case '$eq':
                        wixFilter = wixFilter.eq(fieldId, operandValue);
                        break;
                    case '$ne':
                        wixFilter = wixFilter.ne(fieldId, operandValue);
                        break;
                    case '$gt':
                        wixFilter = wixFilter.gt(fieldId, operandValue);
                        break;
                    case '$gte':
                        wixFilter = wixFilter.ge(fieldId, operandValue);
                        break;
                    case '$lt':
                        wixFilter = wixFilter.lt(fieldId, operandValue);
                        break;
                    case '$lte':
                        wixFilter = wixFilter.le(fieldId, operandValue);
                        break;
                    case '$hasSome':
                        if (Array.isArray(operandValue) && operandValue.length > 0) {
                            wixFilter = wixFilter.hasSome(fieldId, operandValue);
                        }
                        break;
                    case '$in':
                        if (Array.isArray(operandValue) && operandValue.length > 0) {
                            wixFilter = wixFilter.hasSome(fieldId, operandValue);
                        }
                        break;
                    case '$hasAll':
                        if (Array.isArray(operandValue) && operandValue.length > 0) {
                            wixFilter = wixFilter.hasAll(fieldId, operandValue);
                        }
                        break;
                    case '$startsWith':
                        wixFilter = wixFilter.startsWith(fieldId, operandValue);
                        break;
                    case '$endsWith':
                        wixFilter = wixFilter.endsWith(fieldId, operandValue);
                        break;
                    case '$contains':
                        wixFilter = wixFilter.contains(fieldId, operandValue);
                        break;
                    case '$isEmpty':
                        wixFilter = wixFilter.isEmpty(fieldId);
                        break;
                    case '$isNotEmpty':
                        wixFilter = wixFilter.isNotEmpty(fieldId);
                        break;
                    case '$between':
                        if (Array.isArray(operandValue) &&
                            operandValue.length === 2 &&
                            operandValue[0] !== null &&
                            operandValue[1] !== null) {
                            wixFilter = wixFilter.between(fieldId, operandValue[0], operandValue[1]);
                        }
                        break;
                    // Skip unsupported operators
                    default:
                        break;
                }
            }
        }
        else {
            // Direct value means equality
            wixFilter = wixFilter.eq(fieldId, value);
        }
    }
    return wixFilter;
}
/**
 * Shared function to load collection items from Wix Data with pagination support.
 * Returns a WixDataQueryResult that contains items, pagination info, and navigation methods.
 * Uses Wix Data SDK's filter() and and() methods to combine default and user filters.
 */
const loadCollectionItems = async (collectionId, options = {}, sort, userFilter, defaultFilter, singleRefFieldIds = [], multiRefFieldIds = []) => {
    if (!collectionId) {
        throw new Error('No collection ID provided');
    }
    const { limit, skip = 0, returnTotalCount = false } = options;
    let query = items.query(collectionId);
    // Build WixDataFilter objects and combine using Wix Data SDK's and() method
    const hasDefaultFilter = defaultFilter && Object.keys(defaultFilter).length > 0;
    const hasUserFilter = userFilter && Object.keys(userFilter).length > 0;
    if (hasDefaultFilter && hasUserFilter) {
        // Both filters present - combine with and() method
        const defaultWixFilter = buildWixDataFilter(defaultFilter);
        const userWixFilter = buildWixDataFilter(userFilter);
        // Use and() to combine the two filters
        query = query.and(defaultWixFilter).and(userWixFilter);
    }
    else if (hasDefaultFilter) {
        // Only default filter - apply directly
        query = query.and(buildWixDataFilter(defaultFilter));
    }
    else if (hasUserFilter) {
        // Only user filter - apply directly
        query = query.and(buildWixDataFilter(userFilter));
    }
    if (sort && sort.length > 0 && sort[0]) {
        const { fieldName, order } = sort[0];
        if (fieldName) {
            if (order === 'DESC') {
                query = query.descending(fieldName);
            }
            else {
                // Default to ascending if order not specified or is 'ASC'
                query = query.ascending(fieldName);
            }
        }
    }
    if (limit) {
        query = query.limit(limit);
    }
    query = query.skip(skip);
    // Include reference fields if specified
    const allRefFieldIds = [...singleRefFieldIds, ...multiRefFieldIds];
    if (allRefFieldIds.length > 0) {
        query = query.include(...allRefFieldIds);
    }
    return await query.find({ returnTotalCount });
};
/**
 * Implementation of the CMS Collection service that manages reactive collection data.
 */
export const CmsCollectionServiceImplementation = implementService.withConfig()(CmsCollectionServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    const loadingSignal = signalsService.signal(false);
    const fetchingSignal = signalsService.signal(false);
    const errorSignal = signalsService.signal(null);
    // Initialize query result signal
    const queryResultSignal = signalsService.signal(config.queryResult || null);
    // Initialize sort signal
    const sortSignal = signalsService.signal(config.initialSort || []);
    // Initialize filter signal
    const filterSignal = signalsService.signal(config.initialFilter || null);
    // Initialize collection schema signal (internal, not exposed)
    const collectionSchemaSignal = signalsService.signal(config.collectionSchema || null);
    const loadItems = async (options = {}) => {
        const hasNoData = queryResultSignal.get() === null;
        if (hasNoData) {
            loadingSignal.set(true);
        }
        fetchingSignal.set(true);
        errorSignal.set(null);
        try {
            // Merge passed options with config defaults
            const mergedOptions = { ...config.queryOptions, ...options };
            const result = await loadCollectionItems(config.collectionId, mergedOptions, sortSignal.get(), filterSignal.get(), config.defaultFilter, config.singleRefFieldIds, config.multiRefFieldIds);
            queryResultSignal.set(result);
        }
        catch (err) {
            errorSignal.set(extractErrorMessage(err, 'Failed to load collection items'));
            console.error(`Failed to load items from collection "${config.collectionId}":`, err);
        }
        finally {
            if (hasNoData) {
                loadingSignal.set(false);
            }
            fetchingSignal.set(false);
        }
    };
    const invalidate = async () => {
        // Preserve current pagination state when invalidating
        const currentResult = queryResultSignal.get();
        const currentSkip = (currentResult?.currentPage || 0) * (currentResult?.pageSize || 10);
        const currentLimit = currentResult?.pageSize;
        await loadItems({
            skip: currentSkip,
            limit: currentLimit,
        });
    };
    const loadSchema = async () => {
        const schema = await loadCollectionSchema(config.collectionId);
        if (schema) {
            collectionSchemaSignal.set(schema);
        }
    };
    const createItem = async (itemData) => {
        try {
            // Retry schema load if not available
            let schema = collectionSchemaSignal.get();
            if (!schema) {
                await loadSchema();
                schema = collectionSchemaSignal.get();
            }
            const transformedItemData = transformFields(itemData, schema);
            const createdItem = await items.insert(config.collectionId, transformedItemData);
            // Invalidate + refetch to maintain consistency with backend query logic
            await invalidate();
            return createdItem;
        }
        catch (err) {
            console.error(`Failed to create item in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const linkItem = async (params) => {
        try {
            await items.insertReference(config.collectionId, params.referenceFieldId, params.itemId, params.referencedItemIds);
            // Invalidate + refetch to maintain consistency with backend query logic
            await invalidate();
        }
        catch (err) {
            console.error(`Failed to link item in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const updateItem = async (itemId, itemData) => {
        try {
            // Retry schema load if not available
            let schema = collectionSchemaSignal.get();
            if (!schema) {
                await loadSchema();
                schema = collectionSchemaSignal.get();
            }
            const transformedItemData = transformFields(itemData, schema);
            const updatedItem = await items.update(config.collectionId, {
                ...transformedItemData,
                _id: itemId,
            });
            // Invalidate + refetch to maintain consistency with backend query logic
            await invalidate();
            return updatedItem;
        }
        catch (err) {
            console.error(`Failed to update item in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const deleteItem = async (itemId) => {
        try {
            await items.remove(config.collectionId, itemId);
            // Invalidate + refetch to maintain consistency with backend query logic
            await invalidate();
        }
        catch (err) {
            console.error(`Failed to delete item in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const unlinkItem = async (params) => {
        try {
            await items.removeReference(config.collectionId, params.referenceFieldId, params.itemId, params.referencedItemIds);
            // Invalidate + refetch to maintain consistency with backend query logic
            await invalidate();
        }
        catch (err) {
            console.error(`Failed to unlink item in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const fetchFieldOptions = async (fieldId) => {
        const getSchema = async () => {
            let schema = collectionSchemaSignal.get();
            if (!schema) {
                await loadSchema();
                schema = collectionSchemaSignal.get();
            }
            return schema;
        };
        return await fetchFieldOptionsUtil({
            collectionId: config.collectionId,
            fieldId,
            getSchema,
        });
    };
    const createReferencedCollectionItem = async (referenceFieldId, itemData) => {
        try {
            const getSchema = async () => {
                let schema = collectionSchemaSignal.get();
                if (!schema) {
                    await loadSchema();
                    schema = collectionSchemaSignal.get();
                }
                return schema;
            };
            const createdItem = await createReferencedCollectionItemUtil({
                referenceFieldId,
                itemData,
                getSchema,
            });
            return createdItem;
        }
        catch (err) {
            console.error(`Failed to create item in referenced collection for field "${referenceFieldId}" in collection "${config.collectionId}":`, err);
            throw err; // Re-throw for component error handling
        }
    };
    const setSort = (sort) => {
        sortSignal.set(sort);
        // Reload items with new sort, preserving pagination
        loadItems();
    };
    const setFilter = (filter) => {
        filterSignal.set(filter);
        // Reload items with new filter, reset to first page
        loadItems({ skip: 0 });
    };
    const resetFilter = () => {
        filterSignal.set(null);
        // Reload items without filter, reset to first page
        loadItems({ skip: 0 });
    };
    const resetFilterField = (fieldName) => {
        const currentFilter = filterSignal.get() || {};
        const newFilter = { ...currentFilter };
        // Remove the specific field
        delete newFilter[fieldName];
        // If the resulting filter is empty, set it to null
        const finalFilter = Object.keys(newFilter).length > 0 ? newFilter : null;
        filterSignal.set(finalFilter);
        // Reload items with new filter, reset to first page
        loadItems({ skip: 0 });
    };
    const isFiltered = () => {
        const filter = filterSignal.get();
        return filter !== null && Object.keys(filter).length > 0;
    };
    const nextPage = async () => {
        const currentResult = queryResultSignal.get();
        if (!currentResult?.hasNext()) {
            return;
        }
        fetchingSignal.set(true);
        errorSignal.set(null);
        try {
            const nextResult = await currentResult.next();
            queryResultSignal.set(nextResult);
        }
        catch (err) {
            errorSignal.set(extractErrorMessage(err, 'Failed to load next page'));
            console.error(`Failed to load next page from collection "${config.collectionId}":`, err);
        }
        finally {
            fetchingSignal.set(false);
        }
    };
    const prevPage = async () => {
        const currentResult = queryResultSignal.get();
        if (!currentResult?.hasPrev()) {
            return;
        }
        fetchingSignal.set(true);
        errorSignal.set(null);
        try {
            const prevResult = await currentResult.prev();
            queryResultSignal.set(prevResult);
        }
        catch (err) {
            errorSignal.set(extractErrorMessage(err, 'Failed to load previous page'));
            console.error(`Failed to load previous page from collection "${config.collectionId}":`, err);
        }
        finally {
            fetchingSignal.set(false);
        }
    };
    // Load collection schema if not provided in config
    if (!config.collectionSchema) {
        loadSchema();
    }
    // Auto-load items on service initialization only if not pre-loaded
    if (!config.queryResult) {
        loadItems();
    }
    return {
        loadingSignal,
        fetchingSignal,
        errorSignal,
        queryResultSignal,
        sortSignal,
        filterSignal,
        loadItems,
        invalidate,
        nextPage,
        prevPage,
        createItem,
        linkItem,
        updateItem,
        deleteItem,
        unlinkItem,
        fetchFieldOptions,
        createReferencedCollectionItem,
        setSort,
        setFilter,
        resetFilter,
        resetFilterField,
        isFiltered,
        collectionId: config.collectionId,
    };
});
/**
 * Loads initial data for the CMS Collection service with pagination support.
 *
 * @param collectionId - The collection ID to load data from
 * @param options - Query options for pagination and filtering
 * @param sort - Optional sort value
 * @param filter - Optional filter value
 * @param defaultFilter - Optional default filter that's always applied
 * @param singleRefFieldIds - List of field IDs for single reference fields to include
 * @param multiRefFieldIds - List of field IDs for multi reference fields to include
 * @returns Promise resolving to service configuration with queryResult containing all data
 *
 * @example
 * ```tsx
 * // In Astro frontmatter or server action
 * const cmsConfig = await loadCmsCollectionServiceInitialData(
 *   'MyCollection',
 *   { limit: 10, skip: 0 },
 *   undefined,
 *   { status: { $eq: 'published' } },
 *   { color: { $hasSome: ['yellow', 'red'] } },
 *   ['author', 'category'],
 *   ['tags', 'relatedItems']
 * );
 *
 * // Pass to React component
 * <MyPage cmsConfig={cmsConfig} />
 * ```
 */
export const loadCmsCollectionServiceInitialData = async (collectionId, options = {}, sort, filter, defaultFilter, singleRefFieldIds, multiRefFieldIds) => {
    try {
        if (!collectionId) {
            throw new Error('No collection ID provided');
        }
        // Load collection items and schema in parallel
        const [result, collectionSchema] = await Promise.all([
            loadCollectionItems(collectionId, options, sort, filter, defaultFilter, singleRefFieldIds, multiRefFieldIds),
            loadCollectionSchema(collectionId),
        ]);
        return {
            [CmsCollectionServiceDefinition]: {
                collectionId,
                queryResult: result,
                queryOptions: options,
                initialSort: sort,
                initialFilter: filter,
                defaultFilter,
                singleRefFieldIds,
                multiRefFieldIds,
                collectionSchema,
            },
        };
    }
    catch (error) {
        console.error(`Failed to load collection config for "${collectionId}":`, error);
        throw error; // Re-throw to let caller handle 404 logic
    }
};
/**
 * Service binding helper that bundles everything together for the service manager.
 */
export const cmsCollectionServiceBinding = (servicesConfigs) => {
    return [
        CmsCollectionServiceDefinition,
        CmsCollectionServiceImplementation,
        servicesConfigs[CmsCollectionServiceDefinition],
    ];
};
